use std::collections::HashSet;
use std::env;
use std::str::FromStr;

use atty::{self, Stream};

use crate::clap_app;
use clap::ArgMatches;
use console::Term;

#[cfg(windows)]
use ansi_term;

use crate::assets::BAT_THEME_DEFAULT;
use crate::errors::*;
use crate::inputfile::InputFile;
use crate::line_range::{LineRange, LineRanges};
use crate::style::{OutputComponent, OutputComponents, OutputWrap};
use crate::syntax_mapping::SyntaxMapping;
use crate::util::transpose;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum PagingMode {
    Always,
    QuitIfOneScreen,
    Never,
}

#[derive(Clone)]
pub struct Config<'a> {
    /// List of files to print
    pub files: Vec<InputFile<'a>>,

    /// The explicitly configured language, if any
    pub language: Option<&'a str>,

    /// Whether or not to show/replace non-printable characters like space, tab and newline.
    pub show_nonprintable: bool,

    /// The character width of the terminal
    pub term_width: usize,

    /// The width of tab characters.
    /// Currently, a value of 0 will cause tabs to be passed through without expanding them.
    pub tab_width: usize,

    /// Whether or not to simply loop through all input (`cat` mode)
    pub loop_through: bool,

    /// Whether or not the output should be colorized
    pub colored_output: bool,

    /// Whether or not the output terminal supports true color
    pub true_color: bool,

    /// Style elements (grid, line numbers, ...)
    pub output_components: OutputComponents,

    /// Text wrapping mode
    pub output_wrap: OutputWrap,

    /// Pager or STDOUT
    pub paging_mode: PagingMode,

    /// Specifies the lines that should be printed
    pub line_ranges: LineRanges,

    /// The syntax highlighting theme
    pub theme: String,

    /// File extension/name mappings
    pub syntax_mapping: SyntaxMapping,

    /// Command to start the pager
    pub pager: Option<&'a str>,

    /// Whether or not to use ANSI italics
    pub use_italic_text: bool,

    /// Lines to highlight
    pub highlight_lines: Vec<usize>,
}

fn is_truecolor_terminal() -> bool {
    env::var("COLORTERM")
        .map(|colorterm| colorterm == "truecolor" || colorterm == "24bit")
        .unwrap_or(false)
}

pub struct App {
    pub matches: ArgMatches<'static>,
    interactive_output: bool,
}

impl App {
    pub fn new() -> Result<Self> {
        #[cfg(windows)]
        let _ = ansi_term::enable_ansi_support();

        let interactive_output = atty::is(Stream::Stdout);

        Ok(App {
            matches: Self::matches(interactive_output)?,
            interactive_output,
        })
    }

    fn matches(interactive_output: bool) -> Result<ArgMatches<'static>> {
        let mut context = clap_app::CliContext::new(interactive_output);
        let args = context
            .collect_invocation_args()
            .chain_err(|| "Could not parse configuration file")?;
        Ok(context.build_clap_app().get_matches_from(args))
    }

    pub fn configuration_path(&self) -> String {
        clap_app::CliContext::new(self.interactive_output).configuration_path()
    }

    pub fn config(&self) -> Result<Config> {
        let mut context = clap_app::CliContext::new(self.interactive_output);
        let files = self.files();
        let output_components = self.output_components()?;

        let paging_mode = match context.resolve_paging_kind(
            self.matches.value_of("paging"),
            self.matches.occurrences_of("plain"),
            files.contains(&InputFile::StdIn),
            self.interactive_output,
            atty::is(Stream::Stdin),
        ) {
            0 => PagingMode::Always,
            1 => PagingMode::QuitIfOneScreen,
            _ => PagingMode::Never,
        };

        let mut syntax_mapping = SyntaxMapping::new();

        if let Some(values) = self.matches.values_of("map-syntax") {
            for from_to in values {
                let (from, to) = context.parse_map_syntax(from_to).map_err(|err| ErrorKind::Msg(err))?;
                syntax_mapping.insert(from, to);
            }
        }

        Ok(Config {
            true_color: is_truecolor_terminal(),
            language: context.resolve_language(
                self.matches.value_of("language"),
                self.matches.is_present("show-all"),
            ),
            show_nonprintable: self.matches.is_present("show-all"),
            output_wrap: if context.resolve_wrap_none(
                self.matches.value_of("wrap"),
                self.interactive_output,
                output_components.plain(),
            ) {
                OutputWrap::None
            } else {
                OutputWrap::Character
            },
            colored_output: context.resolve_colored_output(
                self.matches.value_of("color"),
                self.interactive_output,
            ),
            paging_mode,
            term_width: self
                .matches
                .value_of("terminal-width")
                .and_then(|w| context.parse_terminal_width(w, Term::stdout().size().1))
                .unwrap_or(Term::stdout().size().1 as usize),
            loop_through: context.should_loop_through(
                self.interactive_output,
                self.matches.value_of("color"),
                self.matches.value_of("decorations"),
            ),
            files,
            tab_width: context.resolve_tab_width(
                self.matches.value_of("tabs"),
                env::var("BAT_TABS").ok(),
                output_components.plain() && paging_mode == PagingMode::Never,
            ),
            theme: context.resolve_theme(
                self.matches.value_of("theme"),
                env::var("BAT_THEME").ok(),
                BAT_THEME_DEFAULT,
            ),
            line_ranges: {
                let parsed = if let Some(values) = self.matches.values_of("line-range") {
                    let mut ranges = Vec::new();
                    for spec in values {
                        let (lower, upper) = context
                            .parse_line_range_bounds(spec)
                            .map_err(|err| ErrorKind::Msg(err))?;
                        ranges.push(LineRange { lower, upper });
                    }
                    ranges
                } else {
                    Vec::new()
                };
                LineRanges::from(parsed)
            },
            output_components,
            syntax_mapping,
            pager: self.matches.value_of("pager"),
            use_italic_text: context.resolve_italic_text(self.matches.value_of("italic-text")),
            highlight_lines: self
                .matches
                .values_of("highlight-line")
                .and_then(|ws| ws.map(|w| w.parse().ok()).collect())
                .unwrap_or_default(),
        })
    }

    fn files(&self) -> Vec<InputFile> {
        let mut context = clap_app::CliContext::new(self.interactive_output);
        self.matches
            .values_of("FILE")
            .map(|values| {
                values
                    .map(|filename| {
                        if context.is_stdin_marker(filename) {
                            InputFile::StdIn
                        } else {
                            InputFile::Ordinary(filename)
                        }
                    })
                    .collect()
            })
            .unwrap_or_else(|| vec![InputFile::StdIn])
    }

    fn output_components(&self) -> Result<OutputComponents> {
        let mut context = clap_app::CliContext::new(self.interactive_output);
        let matches = &self.matches;
        Ok(OutputComponents(
            if matches.value_of("decorations") == Some("never") {
                HashSet::new()
            } else if matches.is_present("number") {
                [OutputComponent::Numbers].iter().cloned().collect()
            } else if matches.is_present("plain") {
                [OutputComponent::Plain].iter().cloned().collect()
            } else {
